		}
		for _, g := range groups {
			if len(g.Hooks) > 0 {
				events = append(events, label)
				break
			}
		}
		return nil
	}
	for _, event := range HookEventSpecs() {
		if err := add(event.Event, event.Label); err != nil {
			return nil, err
		}
	}
	return events, nil
